import debounce from 'lodash.debounce';
import { IDebounceOptions } from '../types';

export function Debounce(duration: number, options?: IDebounceOptions) {
    return function debounceDecorator(target: object, propertyKey: string, descriptor: PropertyDescriptor) {
        return {
            configurable: true,
            enumerable: descriptor.enumerable,
            get(this: { [key: string]: any }) {
                Object.defineProperty(this, propertyKey, {
                    configurable: true,
                    enumerable: descriptor.enumerable,
                    value: debounce(descriptor.value, duration, options)
                });

                return this[propertyKey];
            }
        };
    };
}

export { debounce };
